//! The generated files: their header, and writing or checking them against the committed copies.

use std::fs;
use std::io;
use std::mem;
use std::path::Path;

/// How to regenerate, from `packages/browseros-agent`. Printed wherever output is stale.
pub const REGENERATE: &str =
    "NEO_RUNTIME_SPEC_CODEGEN=1 cargo run -p neo-runtime-spec --example codegen";

/// The start of every generated file, which also tells `--check` that a file is generated.
const MARKER: &str = "// @generated by neo-runtime-spec's translator (codegen/)";

/// The header of a generated file, as `//` comments, which Rust and TypeScript share.
pub fn header(sha256: &str) -> Vec<String> {
    vec![
        format!("{MARKER} from spec/ with"),
        format!("// sha256 {sha256}."),
        "// Do not edit: change spec/, then run".to_owned(),
        format!("// `{REGENERATE}`."),
    ]
}

/// The column limit of generated files, matching `rustfmt.toml`.
pub const MAX_WIDTH: usize = 100;

/// `line` as lines of at most `width` characters, broken at spaces. A line that already fits
/// stays as written, so a doc author's own line breaks survive.
pub fn wrap(line: &str, width: usize) -> Vec<String> {
    if line.chars().count() <= width {
        return vec![line.to_owned()];
    }
    let mut lines = Vec::new();
    let mut current = String::new();
    for word in line.split(' ') {
        if !current.is_empty() && current.chars().count() + 1 + word.chars().count() > width {
            lines.push(mem::take(&mut current));
        }
        if !current.is_empty() {
            current.push(' ');
        }
        current.push_str(word);
    }
    lines.push(current);
    lines
}

/// A rendered file and its path relative to the crate.
pub struct Rendered {
    pub path: &'static str,
    pub contents: String,
}

#[derive(Clone, Copy, PartialEq, Eq)]
pub enum Mode {
    /// Write each file whose bytes differ and delete stale generated files. Unchanged files are
    /// left alone, so their mtimes, and Cargo's rebuild decisions, stay put.
    Write,
    /// Write nothing; report how the committed files differ.
    Check,
}

/// How the committed files differed from the rendered ones.
#[derive(Default)]
pub struct Drift {
    pub missing: Vec<&'static str>,
    /// With the first line (1-based) that differs.
    pub changed: Vec<(&'static str, usize)>,
    /// Files in `src/` or `ts/` that carry the generated header but are no longer rendered.
    pub unexpected: Vec<String>,
}

impl Drift {
    pub fn is_empty(&self) -> bool {
        self.missing.is_empty() && self.changed.is_empty() && self.unexpected.is_empty()
    }

    /// One line per differing file, saying what `mode` found or did about it.
    pub fn lines(&self, mode: Mode) -> Vec<String> {
        let mut lines = Vec::new();
        for path in &self.missing {
            lines.push(match mode {
                Mode::Write => format!("wrote {path}"),
                Mode::Check => format!("missing {path}"),
            });
        }
        for (path, line) in &self.changed {
            lines.push(match mode {
                Mode::Write => format!("rewrote {path} from line {line}"),
                Mode::Check => format!("stale {path}: differs from line {line}"),
            });
        }
        for path in &self.unexpected {
            lines.push(match mode {
                Mode::Write => format!("deleted {path}, which is generated but no longer rendered"),
                Mode::Check => format!("stale {path}: generated, but no longer rendered"),
            });
        }
        lines
    }
}

/// Compares each rendered file with its committed copy and, under [`Mode::Write`], replaces
/// what differs.
pub fn apply(crate_dir: &Path, rendered: &[Rendered], mode: Mode) -> io::Result<Drift> {
    let mut drift = Drift::default();
    for file in rendered {
        let path = crate_dir.join(file.path);
        match fs::read(&path) {
            Ok(committed) if committed == file.contents.as_bytes() => continue,
            Ok(committed) => {
                drift.changed.push((
                    file.path,
                    first_difference(&committed, file.contents.as_bytes()),
                ));
            }
            Err(error) if error.kind() == io::ErrorKind::NotFound => drift.missing.push(file.path),
            Err(error) => return Err(error),
        }
        if mode == Mode::Write {
            if let Some(parent) = path.parent() {
                fs::create_dir_all(parent)?;
            }
            fs::write(&path, &file.contents)?;
        }
    }
    for dir in ["src", "ts"] {
        let entries = match fs::read_dir(crate_dir.join(dir)) {
            Ok(entries) => entries,
            Err(error) if error.kind() == io::ErrorKind::NotFound => continue,
            Err(error) => return Err(error),
        };
        for entry in entries {
            let path = entry?.path();
            let Some(name) = path.file_name().and_then(|name| name.to_str()) else {
                continue;
            };
            let relative = format!("{dir}/{name}");
            if rendered.iter().any(|file| file.path == relative) || !path.is_file() {
                continue;
            }
            if fs::read(&path)?.starts_with(MARKER.as_bytes()) {
                if mode == Mode::Write {
                    fs::remove_file(&path)?;
                }
                drift.unexpected.push(relative);
            }
        }
    }
    drift.unexpected.sort();
    Ok(drift)
}

/// The first line, counting from 1, on which `committed` and `rendered` differ.
fn first_difference(committed: &[u8], rendered: &[u8]) -> usize {
    let mut line = 1;
    for (a, b) in committed.iter().zip(rendered) {
        if a != b {
            return line;
        }
        if *a == b'\n' {
            line += 1;
        }
    }
    // One is a prefix of the other, so they differ where the shorter one ends.
    line
}
